def brute_force_min_transversal(vertices, edges):
    from itertools import combinations
    if not edges: return set(), 0
    v_list = sorted(vertices)
    for k in range(1, len(v_list) + 1):
        for combo in combinations(v_list, k):
            T = set(combo)
            if all(T & e for e in edges):
                return T, k
    return set(v_list), len(v_list)

def greedy_hitting_set(vertices, edges):
    from collections import defaultdict
    T, remaining = set(), list(edges)
    verts = set(vertices)
    while remaining:
        deg = defaultdict(int)
        for e in remaining:
            for v in e:
                if v in verts and v not in T: deg[v] += 1
        if not deg: break
        best = max(deg, key=deg.get)
        T.add(best); verts.discard(best)
        remaining = [e for e in remaining if best not in e]
    return T, len(T)

def sunflower_branch(vertices, edges, d):
    from itertools import combinations
    if not edges: return set(), 0
    # Try to find sunflower of size d+1
    for combo in combinations(range(len(edges)), d+1):
        group = [edges[i] for i in combo]
        pairs = list(combinations(group, 2))
        if not pairs: continue
        kernel = pairs[0][0] & pairs[0][1]
        if all(e1 & e2 == kernel for e1, e2 in pairs):
            if kernel:
                best = None
                for v in kernel:
                    sub_edges = [e for e in edges if v not in e]
                    sub_T, _ = sunflower_branch(vertices - {v}, sub_edges, d)
                    cand = sub_T | {v}
                    if best is None or len(cand) < len(best):
                        best = cand
                return best, len(best)
    # Fallback to greedy
    return greedy_hitting_set(vertices, edges)

def encode_monotone_sat(vertices, edges):
    var_map = {v: i+1 for i, v in enumerate(sorted(vertices))}
    clauses = [[var_map[v] for v in sorted(e)] for e in edges]
    lines = [f"p cnf {len(var_map)} {len(clauses)}"]
    for c in clauses:
        lines.append(' '.join(map(str, c)) + ' 0')
    return '
'.join(lines), var_map
